use vstd::prelude::*;

verus! {

// A small helper predicate for “is the (mathematical) zero complex number”.
spec fn is_zero_complex(z: (f64, f64)) -> bool {
    z.0 == 0.0 && z.1 == 0.0
}

fn imag(val: Vec<(f64, f64)>) -> (out: Vec<f64>)
    ensures
        // Same length
        out.len() == val.len(),
        // Pointwise: output is the imaginary part (second component)
        forall|i: int| 0 <= i < val.len() ==> out[i] == val[i].1,
        // If imag part is 0.0 then output is 0.0
        forall|i: int| 0 <= i < val.len() && val[i].1 == 0.0 ==> out[i] == 0.0,
        // If not the zero complex number, output is still the imag part
        forall|i: int|
            0 <= i < val.len() && !is_zero_complex(val[i]) ==> out[i] == val[i].1,
{
    let n = val.len();
    let mut out: Vec<f64> = Vec::with_capacity(n);

    let mut i: usize = 0;
    while i < n
        invariant
            n == val.len(),
            out.len() == i,
            i <= n,
            // All elements produced so far are exactly the imag parts
            forall|k: int| 0 <= k < i ==> out[k] == val[k].1,
        decreases n - i,
    {
        // Push the imaginary part
        out.push(val[i].1);
        i += 1;
    }

    // Establish the two “conditional” properties from the pointwise equality.
    assert(forall|j: int| 0 <= j < val.len() && val[j].1 == 0.0 ==> out[j] == 0.0);
    assert(forall|j: int| 0 <= j < val.len() && !is_zero_complex(val[j]) ==> out[j] == val[j].1);

    out
}

} // verus!

